#include "joint_work/audit/common.hpp"
#include <random>
#include <chrono>
using B64=uint64_t;
int main(int argc,char**argv){if(argc!=6)return 2;const L cut=stoull(argv[5]);Reader r(argv[1]);assert(cut<r.counts[0]);ifstream in(argv[2],ios::binary);ofstream out(argv[3],ios::binary);U nb=0;in.read((char*)&nb,4);vector<U> S(840),E(49140);vector<bool> qs(r.Q),bs(r.B);for(auto p:r.regs){U n,l;memcpy(&n,p.ptr,4);memcpy(&l,p.ptr+4,4);string name(p.ptr+8,n);assert(l==12);U j=stoul(name.substr(1));for(U k=0;k<12;k++){U v;memcpy(&v,p.ptr+8+n+4*k,4);v&=0x7fffffff;if(name[0]=='S'){S[12*j+k]=v;qs[v]=true;}else if(name[0]=='E'){E[12*j+k]=v;bs[v]=true;}else abort();}}vector<B64> q(r.Q),b(r.B),x(840),y(49140);vector<B64> stack;mt19937_64 rng(stoull(argv[4]));B64 counts[5]={};for(U shot=0;shot<nb;shot++){U n;B64 want;in.read((char*)&n,4);in.read((char*)x.data(),8*x.size());in.read((char*)y.data(),8*y.size());in.read((char*)&want,8);assert(in&&n<=64);B64 mask=n==64?~0ULL:((1ULL<<n)-1);fill(q.begin(),q.end(),0);fill(b.begin(),b.end(),0);for(U j=0;j<S.size();j++)q[S[j]]=x[j];for(U j=0;j<E.size();j++)b[E[j]]=y[j];r.reset();stack={mask};B64 phase=0,paid=0;for(L i=0;i<cut;i++){auto g=r.read(i);int op=g.op&127;if(g.op==129){stack.push_back(stack.back()&b[g.cond]);continue;}if(op==1){assert(stack.size()>1);stack.pop_back();continue;}B64 k=stack.back();if(g.op&128)k&=b[g.cond];U a=g.a,d=g.b,t=g.t;B64 delta;if((op&0x30)==0x30)paid+=__builtin_popcountll(k);switch(op){case 0x11:q[a]^=k;break;case 0x12:q[a]&=~k;break;case 0x21:q[d]^=k&q[a];break;case 0x22:delta=k&(q[a]^q[d]);q[a]^=delta;q[d]^=delta;break;case 0x31:q[t]^=k&q[a]&q[d];break;case 0x32:delta=k&q[a]&(q[d]^q[t]);q[d]^=delta;q[t]^=delta;break;case 0x50:{B64 m=rng();phase^=k&m&q[a];b[g.bit]=(b[g.bit]&~k)|(m&k);q[a]&=~k;break;}case 0x40:b[g.bit]&=~k;break;case 0x41:b[g.bit]|=k;break;case 0x42:b[g.bit]^=k;break;case 0:phase^=k;break;case 0x10:phase^=k&q[a];break;case 0x20:phase^=k&q[a]&q[d];break;case 0x30:phase^=k&q[a]&q[d]&q[t];break;default:cerr<<"bad opcode "<<hex<<op<<dec<<" at "<<i<<endl;return 3;}}out.write((char*)&n,4);out.write((char*)q.data(),8*q.size());}assert(out.good());}
